with parsed as (select id, service, host, log_ts, level, latency_ms, status_code, payload_json, context, get_json_object(payload_json, '$.user.tier') as user_tier, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, cast((status_code & 8) != 0 as int) as is_flagged, coalesce(context['region'], 'direct') as region_or_default from app_logs where status_code between 282 and 376) select level, percentile_approx(is_flagged, 0.5) as is_flagged_p50, sort_array(collect_set(service)) as service_list, corr(status_code, latency_ms) as corr_status_code_latency_ms, approx_percentile(is_flagged, 0.9) as is_flagged_p90, grouping_id() as grouping_id from parsed group by cube (level) order by corr_status_code_latency_ms nulls first;
